pair<int,int> twoSumSorted(vector<int>& a, int target) {
    int l = 0, r = a.size() - 1;
    while (l < r) {
        int s = a[l] + a[r];
        if (s == target) return {l, r};
        else if (s < target) ++l;
        else --r;
    }
    return {-1, -1};
}

def two_sum_sorted(a, target):
    l, r = 0, len(a) - 1
    while l < r:
        s = a[l] + a[r]
        if s == target:
            return (l, r)
        elif s < target:
            l += 1          # need a bigger sum
        else:
            r -= 1          # need a smaller sum
    return (-1, -1)

class Solution {
public:
    vector<int> twoSum(vector<int>& a, int target) {
        int i = 0, j = a.size() - 1;
        while (i < j) {
            int s = a[i] + a[j];
            if (s == target) return {i + 1, j + 1};
            if (s < target) i++; else j--;
        }
        return {};
    }
};

class Solution:
    def twoSum(self, a: list[int], target: int) -> list[int]:
        i, j = 0, len(a) - 1
        while i < j:
            s = a[i] + a[j]
            if s == target:
                return [i + 1, j + 1]
            if s < target:
                i += 1
            else:
                j -= 1
        return []

class Solution {
public:
    bool isPalindrome(string s) {
        int i = 0, j = s.size() - 1;
        while (i < j) {
            while (i < j && !isalnum(s[i])) i++;
            while (i < j && !isalnum(s[j])) j--;
            if (tolower(s[i]) != tolower(s[j])) return false;
            i++; j--;
        }
        return true;
    }
};

class Solution:
    def isPalindrome(self, s: str) -> bool:
        i, j = 0, len(s) - 1
        while i < j:
            while i < j and not s[i].isalnum():
                i += 1
            while i < j and not s[j].isalnum():
                j -= 1
            if s[i].lower() != s[j].lower():
                return False
            i += 1; j -= 1
        return True

class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& a) {
        sort(a.begin(), a.end());
        vector<vector<int>> res;
        int n = a.size();
        for (int i = 0; i < n - 2; i++) {
            if (i && a[i] == a[i - 1]) continue;
            int l = i + 1, r = n - 1;
            while (l < r) {
                int s = a[i] + a[l] + a[r];
                if (s < 0) l++;
                else if (s > 0) r--;
                else {
                    res.push_back({a[i], a[l], a[r]});
                    while (l < r && a[l] == a[l + 1]) l++;
                    while (l < r && a[r] == a[r - 1]) r--;
                    l++; r--;
                }
            }
        }
        return res;
    }
};

class Solution:
    def threeSum(self, a: list[int]) -> list[list[int]]:
        a.sort()
        res, n = [], len(a)
        for i in range(n - 2):
            if i and a[i] == a[i - 1]:
                continue
            l, r = i + 1, n - 1
            while l < r:
                s = a[i] + a[l] + a[r]
                if s < 0:
                    l += 1
                elif s > 0:
                    r -= 1
                else:
                    res.append([a[i], a[l], a[r]])
                    while l < r and a[l] == a[l + 1]:
                        l += 1
                    while l < r and a[r] == a[r - 1]:
                        r -= 1
                    l += 1; r -= 1
        return res

class Solution {
public:
    int maxArea(vector<int>& h) {
        int i = 0, j = h.size() - 1, best = 0;
        while (i < j) {
            best = max(best, (j - i) * min(h[i], h[j]));
            if (h[i] < h[j]) i++; else j--;
        }
        return best;
    }
};

class Solution:
    def maxArea(self, h: list[int]) -> int:
        i, j, best = 0, len(h) - 1, 0
        while i < j:
            best = max(best, (j - i) * min(h[i], h[j]))
            if h[i] < h[j]:
                i += 1
            else:
                j -= 1
        return best

class Solution {
public:
    int trap(vector<int>& h) {
        int i = 0, j = h.size() - 1, lmax = 0, rmax = 0, water = 0;
        while (i < j) {
            if (h[i] < h[j]) { lmax = max(lmax, h[i]); water += lmax - h[i]; i++; }
            else { rmax = max(rmax, h[j]); water += rmax - h[j]; j--; }
        }
        return water;
    }
};

class Solution:
    def trap(self, h: list[int]) -> int:
        i, j = 0, len(h) - 1
        lmax = rmax = water = 0
        while i < j:
            if h[i] < h[j]:
                lmax = max(lmax, h[i]); water += lmax - h[i]; i += 1
            else:
                rmax = max(rmax, h[j]); water += rmax - h[j]; j -= 1
        return water
